-- Warehouse Procurement: daily order lines, close batches, admin Jira template.
-- Apply to Supabase (SQL editor or migration runner) before using procurement in production.

CREATE TABLE IF NOT EXISTS "procurement_order_lines" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "day_key" TEXT NOT NULL,
  "link" TEXT NOT NULL,
  "quantity" INTEGER NOT NULL DEFAULT 1,
  "notes" TEXT NOT NULL DEFAULT '',
  "created_by_email" TEXT NOT NULL,
  "created_by_name" TEXT NOT NULL DEFAULT '',
  "status" TEXT NOT NULL DEFAULT 'open',
  "batch_id" INTEGER,
  "submitted_at" TIMESTAMPTZ,
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  "created_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "procurement_order_lines_day_status_idx"
  ON "procurement_order_lines" ("day_key", "status");

CREATE TABLE IF NOT EXISTS "procurement_batches" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "day_key" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "line_count" INTEGER NOT NULL DEFAULT 0,
  "jira_issue_key" TEXT NOT NULL DEFAULT '',
  "jira_issue_url" TEXT NOT NULL DEFAULT '',
  "slack_channel_id" TEXT NOT NULL DEFAULT '',
  "slack_message_ts" TEXT NOT NULL DEFAULT '',
  "dry_run" BOOLEAN NOT NULL DEFAULT false,
  "error_message" TEXT NOT NULL DEFAULT '',
  "created_at" TIMESTAMPTZ DEFAULT now(),
  "submitted_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX IF NOT EXISTS "procurement_batches_day_key_uidx"
  ON "procurement_batches" ("day_key");

CREATE TABLE IF NOT EXISTS "procurement_settings" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "jira_summary_template" TEXT NOT NULL,
  "jira_description_template" TEXT NOT NULL,
  "slack_channel_id" TEXT NOT NULL DEFAULT '',
  "slack_ping_user_id" TEXT NOT NULL DEFAULT '',
  "jira_project_key" TEXT NOT NULL DEFAULT '',
  "jira_issue_type" TEXT NOT NULL DEFAULT '',
  "updated_by" TEXT NOT NULL DEFAULT '',
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  "created_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("id")
);
